let strategy={},versions=[],jobs=[],session=null,workspaceRevision=0,saveChain=Promise.resolve(),saveBlocked=false,productionLesson=null,productionTab='Brief',productionVersion=null,editorDraft=null,metricsPlatform='YouTube',metricsWindow='72h';
const G=GrowthMetrics;
const newItems=[['overview','◫','Command centre'],['strategy','◎','Strategy & channels'],['personas','♙','Audience personas'],['competitors','◈','Competitor intelligence'],['pillars','▤','Content pillars'],['calendar','▦','30-day calendar'],['backlog','+','Idea backlog'],['studio','▷','Video studio'],['approvals','✓','Approvals'],['queue','↓','Approved downloads'],['reports','▥','Performance'],['retention','⌁','Retention lab'],['weekly','▣','Weekly review'],['monthly','▣','30-day review'],['experiments','⚗','Experiments'],['monetization','₹','Monetization'],['recommendations','✦','Recommendations'],['agents','⌘','Agent team'],['maps','⌖','Maps & locations'],['assets','▧','Sia & assets'],['plan','≡','Operating playbook'],['settings','⚙','Connections']];items.splice(0,items.length,...newItems);
async function api(path,options={}){let r;try{r=await fetch('/api/'+path,{...options,headers:{'Content-Type':'application/json',...options.headers},body:options.body===undefined?undefined:JSON.stringify(options.body)})}catch{throw Error('Connection unavailable. Your draft remains on screen.')}let b;try{b=await r.json()}catch{throw Error('Server connection unavailable.')}if(!r.ok)throw Object.assign(Error(b.error||'Request failed'),{status:r.status,missing:b.missing});return b;}
persist=function(){if(saveBlocked||!session)return;const snapshot=JSON.parse(JSON.stringify(state));delete snapshot.role;saveChain=saveChain.then(async()=>{if(saveBlocked)return;try{const r=await api('workspace',{method:'PUT',body:{state:snapshot,revision:workspaceRevision}});workspaceRevision=r.revision;$('#saveState').textContent='Saved to workspace';}catch(e){saveBlocked=true;$('#saveState').textContent='Save needs attention';toast(e.message);}});};
editable=()=>session&&['Owner','Manager','Creator','Approver'].includes(session.user.role);canApprove=()=>session&&['Owner','Manager','Approver'].includes(session.user.role);
function saveGrowth(action,target='workspace'){audit(action,target);}
function objectCard(obj){if(obj===null||obj===undefined)return '<span class="subtle">Not verified</span>';if(typeof obj==='string')return `<p>${esc(obj)}</p>`;if(typeof obj==='number'||typeof obj==='boolean')return `<p>${esc(obj)}</p>`;if(Array.isArray(obj))return `<ul>${obj.map(x=>`<li>${typeof x==='object'?objectCard(x):esc(x)}</li>`).join('')}</ul>`;return Object.entries(obj).map(([k,v])=>`<div class="fact"><strong>${esc(k.replace(/([a-z])([A-Z])/g,'$1 $2').replaceAll('_',' '))}</strong>${objectCard(v)}</div>`).join('');}
const empty=(title,text)=>`<div class="empty"><h3>${esc(title)}</h3><p>${esc(text)}</p></div>`;
function packStatus(){return `${all().length} lessons · ${versions.length} saved versions · ${jobs.filter(j=>j.status==='Completed').length} presenter drafts`;}
const oldRender=render;
render=function(){view=location.hash.slice(1)||'overview';if(!items.some(x=>x[0]===view))view='overview';initNav();const f={overview:growthOverview,strategy:strategyView,personas:personasView,competitors:competitorsView,pillars:pillarsView,backlog:PhaseOne.ideas,calendar:growthCalendar,studio:PhaseOne.studio,approvals:PhaseOne.approvals,queue:PhaseOne.downloads,reports:performanceView,retention:retentionView,weekly:()=>reviewView('weekly'),monthly:()=>reviewView('monthly'),experiments:experimentsView,monetization:monetizationView,recommendations:recommendationView,agents,maps,assets,plan:growthPlan,settings:connectionsView}[view];$('#main').innerHTML=f();bind();bindGrowth();bindProviderSettings();PhaseOne.bindPage();$('#pause').hidden=true;};
function growthOverview(){const m=state.measurements||[];return heading('Make people speak.\nThen make them return.','SpeakX · October 1–30, 2026 · Organic',`<button class="primary" data-go="studio">Open video studio</button>`)+`<div class="stats"><article><span>Original Sia lessons</span><strong>30</strong><small>19 studio · 11 location · 5 map reveals</small></article><article><span>Channel placements</span><strong>180</strong><small>90 videos · 60 X posts · 30 Story sets</small></article><article><span>Measured posts</span><strong>${G.latest(m).length}</strong><small>${m.length?'Imported observations':'No post-level imports yet'}</small></article><article><span>Media versions</span><strong>${versions.length}</strong><small>Every revision stays traceable</small></article></div><div class="split"><section class="panel hero-panel"><div class="copy"><span class="tag">One useful sentence. Every day.</span><h2>“I know it.<br>I just can’t say it.”</h2><p>Sia turns that pause into a speaking turn. Small, practical lessons with a model, a practice moment and a reason to return.</p><button data-go="strategy">See the growth strategy</button></div><div class="portrait"><img src="assets/sia-board.png" alt="Sia character reference"></div></section><section class="panel"><h2>This month’s operating rules</h2><ul class="checks"><li>Organic distribution; no paid boosts</li><li>Sia is the only person and voice</li><li>Useful answer before the end of every lesson</li><li>Save versions before generating</li><li>Human approval before a final post</li><li>Compare matched data, not raw view totals</li></ul><button data-go="settings">Resolve launch dependencies</button></section></div><section class="panel"><div class="row"><h2>The next production batch</h2><span class="subtle">${packStatus()}</span></div>${all().slice(0,4).map(row).join('')}</section><section class="panel"><h2>What we know today</h2><p>Instagram has 107,120 followers; Facebook displays 213K. The strategy starts with established audiences on those channels, and a small X account.</p><p>Commercial use of Sia confirmed by you. October dates confirmed. Maps and character board received. Check Connections for current provider readiness. Phase 1 ends with an approved download for manual publishing.</p><p>X public snapshot, Sep 21: 54 posts and 8 followers. This is an account observation, not a reach or conversion baseline.</p><p><a href="https://speakx.ai/" target="_blank" rel="noreferrer">SpeakX website</a> → YouTube @speakx_ai · Instagram @speakx_ai · Facebook /speakxai · X @SpeakxOnX.</p></section>`;}
function strategyView(){return heading('Own the speaking moment.','Positioning, native channel playbooks and resources')+`<section class="panel">${objectCard(strategy.positioning)}</section><section class="panel"><h2>Current account strategy</h2>${objectCard(strategy.strategicUpdate)}</section><section class="panel"><h2>Known inputs & assumptions</h2><p>Organic-only; 30 days; India/IST; Hinglish first; Sia commercial rights confirmed. Existing account identities found via SpeakX’s website. Revenue target, subscription pricing, team capacity and production spending cap remain unconfirmed.</p><p>Do not reuse published outcome statistics or testimonials in a new campaign until their evidence and reuse permissions are reviewed.</p></section><div class="cards">${(strategy.channelPlaybooks||[]).map(x=>`<section class="panel">${objectCard(x)}</section>`).join('')}</div><section class="panel"><h2>Resource plan</h2>${objectCard(strategy.resourcePlan)}</section><section class="panel"><h2>Organic growth loops</h2>${objectCard(strategy.growthLoops)}</section>`;}
function personasView(){return heading('One audience. Different moments.','Eight planning personas · validate against real audience data')+`<div class="cards">${(strategy.personas||[]).map(x=>`<section class="panel">${objectCard(x)}</section>`).join('')}</div>`;}
function competitorsView(){return heading('Learn the patterns. Keep our voice.','Public research · observations separated from hypotheses')+`<p class="subtle">No unverified follower counts, posting frequency or “best performing” claims. References are in the evidence library below.</p><div class="cards">${(strategy.competitors||[]).map(x=>`<section class="panel">${objectCard(x)}</section>`).join('')}</div><section class="panel"><h2>Evidence library</h2>${(strategy.sources||[]).map(x=>`<div class="list-row"><div>${objectCard(x)}</div></div>`).join('')}</section>`;}
function pillarsView(){return heading('A balanced reason to follow.','30-day mix: 15 discovery · 8 trust · 4 community · 3 conversion')+`<section class="panel"><p>The mix is an editorial allocation, not a growth forecast. All 17 pillars are available, but every lesson has one primary job. Product proof uses approved product assets; Sia never impersonates a customer or founder.</p></section><div class="cards">${(strategy.pillars||[]).map(x=>`<section class="panel">${objectCard(x)}</section>`).join('')}</div>`;}
function backlogView(){return heading('Questions worth answering.','Turn learning questions into the next Sia episode')+`<section class="panel"><label for="ideaTitle">Learner question / idea</label><input id="ideaTitle" placeholder="How do I ask for a deadline extension?"><label for="ideaEvidence">Evidence and source</label><textarea id="ideaEvidence" placeholder="A real comment link or an explicitly labelled idea hypothesis"></textarea><button id="addIdea" class="primary">Add idea</button></section><section class="panel">${(state.ideas||[]).map(i=>`<div class="list-row"><div class="grow"><strong>${esc(i.title)}</strong><small>${esc(i.evidence)} · ${esc(i.status)}</small></div><button data-idea-promote="${i.id}">Create brief</button></div>`).join('')||empty('Start with real questions','Add learner questions, search queries and manager observations. No comments have been fetched.')}</section>`;}
function growthCalendar(){return heading('30 days. One clear speaking journey.','October 1–30 · all posting times IST',`<button id="exportCSV">Export calendar CSV</button>`)+`<div class="toolbar"><input id="growthSearch" aria-label="Search calendar" placeholder="Search lesson, persona, keyword…"><select id="growthSetting" aria-label="Filter setting"><option value="all">All settings</option><option value="studio">Studio</option><option value="location">Location</option></select><select id="growthFlagship" aria-label="Filter flagship"><option value="all">All lessons</option><option value="yes">10 flagship episodes</option></select><select id="growthFunnel" aria-label="Filter funnel"><option value="all">All content jobs</option>${[...new Set(all().map(e=>e.contentJob))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><section class="panel"><div class="row"><span>Mon–Fri: YT 18:30 · IG 19:30 · FB 20:00</span><span>Sat–Sun: YT 10:30 · IG 11:00 · FB 11:30</span></div><p class="subtle">X 08:30 / 19:00 · Stories 13:00. Initial hypotheses; use audience activity and controlled tests to refine. Oct 31 is outside this campaign.</p><div id="growthLessons">${growthRows(all())}</div></section>`;}
function growthRows(es){return es.map(e=>`<div class="list-row"><div class="datebox">${e.date.slice(8)}<small>${esc(e.day.slice(0,3))}</small></div><div class="grow"><strong>${esc(e.topic)} ${e.flagship?'<span class="badge approved">Flagship</span>':''}</strong><small>${esc(e.persona)} · ${esc(e.settingMode)} · ${esc(e.contentJob)} · ${esc(e.show)}</small><small>${esc(e.hooks[0].text)}</small></div><span class="subtle">${e.scorecard.normalizedScore}/100<br>editorial score</span><button data-open="${e.id}">Open production</button></div>`).join('')||empty('No matching lessons','Change your filters.');}
function growthStudio(){return heading('From idea to a Sia episode.','Script → voice → presenter draft → captions → final review',`<button data-go="settings">Provider setup</button>`)+`<section class="panel"><p>${packStatus()}. Generation uses a saved version. Cartesia supplies the voice; Kie supplies the presenter video. A generated presenter draft still needs caption finishing and final media QA.</p></section><div class="cards">${all().map(e=>`<section class="panel episode-card"><div class="row"><span class="tag">OCT ${e.date.slice(8)}</span><span class="subtle">${e.flagship?'Flagship · ':''}${e.estimatedDurationSeconds}s plan</span></div><h3>${esc(e.topic)}</h3><p class="quote">${esc(e.hooks[0].text)}</p><p class="subtle">${esc(e.settingMode)} · ${esc(e.persona)}</p><div class="actions"><button class="primary" data-open="${e.id}">Script & prompt</button><button data-gen-open="${e.id}">Generate video</button></div></section>`).join('')}</div>`;}
function versionFor(e){return productionVersion?versions.find(v=>v.id===productionVersion):versions.find(v=>v.lesson_id===e.id);}
function draftFor(e){const v=versionFor(e);return v?structuredClone(v.body):{lessonId:e.id,script:e.script,prompt:withSiaReferencePolicy(e.finalPrompt),scenes:structuredClone(e.scenes),language:'Hinglish',platform:'Instagram',aspectRatio:'9:16',duration:e.duration,captionStyle:'Two-line high contrast',referenceKey:'',referenceApproved:false,rightsConfirmed:true,note:'Initial production draft',parentId:null};}
openDetail=function(id,tab='Script'){PhaseOne.open(id,['Script','Review','Versions','Generate','Finish','Final Review','History'].includes(tab)?tab:'Script').catch(e=>toast(e.message));};
function showProduction(){const e=byId(productionLesson),v=versionFor(e),d=editorDraft;const dialog=$('#detail');dialog.innerHTML=`<div class="dialog-head"><div><small>${esc(e.date)} · ${esc(e.show)} · ${esc(e.persona)}</small><h2>${esc(d.test?'Sia voice & identity test':e.topic)}</h2></div><button id="closeProduction" aria-label="Close production">Close</button></div><div class="dialog-body"><div class="tabs">${['Brief','Script','Prompt','Versions','Generate','Review'].map(t=>`<button data-production-tab="${t}" class="${t===productionTab?'selected':''}">${t}</button>`).join('')}</div>${productionTab==='Brief'?`<div class="split"><section><span class="tag">Editorial potential ${e.scorecard.normalizedScore}/100</span><h3>Three ways to open</h3>${e.hooks.map(h=>`<div class="panel"><b>${h.id} · ${h.chosen?'Selected':'Alternative'}</b><p>${esc(h.text)}</p><small>${esc(h.reason)}</small></div>`).join('')}<h3>Retention & weakness</h3><p>${esc(e.retentionLogic)}</p><p>${esc(e.experiment.weakness)}</p></section><section><h3>Audience & format</h3><p>${esc(e.persona)} · ${esc(e.pillar)} · ${esc(e.contentJob)}</p><p>${esc(e.location)} · ${e.mapReveal?'One-second map at 2–3s, under the first answer':'No map overlay'}</p><h3>Search hypothesis</h3><p>${e.searchTerms.map(esc).join(' · ')}</p><h3>Thumbnail / cover</h3><p class="quote">${esc(e.thumbnailCopy)}</p><h3>Native channel package</h3>${objectCard(e.platformCopy)}</section></div><details><summary>16-factor scoring and experiment</summary>${objectCard(e.scorecard)}${objectCard(e.experiment)}</details>`:productionTab==='Script'?`<label for="productionScript">Spoken script</label><textarea id="productionScript" rows="6">${esc(d.script)}</textarea><button id="redistribute">Distribute revised script across scenes</button><p class="subtle">Timings are estimates. Listen to the actual voice, align captions and validate pacing before export.</p><div class="scene-grid">${d.scenes.map((s,i)=>`<section class="panel"><h3>Scene ${i+1} · ${s.startSeconds}–${s.endSeconds}s</h3><label for="sceneVoice${i}">Sia voiceover</label><textarea id="sceneVoice${i}" data-scene-voice="${i}">${esc(s.voiceover)}</textarea><label for="sceneShot${i}">Shot direction</label><textarea id="sceneShot${i}" data-scene-shot="${i}">${esc(s.shot)}</textarea><p>${esc(s.edit)}</p><small>Caption text follows this voiceover. ${s.pauseSeconds||0}s practice hold.</small></section>`).join('')}</div><div class="actions"><button id="syncSceneScript">Use scene edits as final script</button><button id="exportSrt">Export draft SRT</button></div><p class="subtle">SRT is proportionally timed from the plan, not audio-aligned. Never treat it as final subtitles.</p>`:productionTab==='Prompt'?`<div class="toolbar"><label>Platform<select id="productionPlatform">${['Instagram','YouTube','Facebook','X'].map(x=>`<option ${d.platform===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Language<input id="productionLanguage" value="${esc(d.language)}"></label><label>Aspect ratio<select id="productionAspect"><option>9:16</option></select></label><label>Planned seconds<input type="number" min="10" max="60" id="productionDuration" value="${d.duration}"></label></div><label for="productionPrompt">Full editable production prompt</label><textarea id="productionPrompt" class="prompt-editor">${esc(d.prompt)}</textarea><button id="rebuildPrompt">Rebuild from current scenes</button><p class="subtle">The production prompt includes finishing instructions. Kie creates the presenter draft; subtitles, map cutaways and logo overlays are finishing steps. The provider receives Sia-only constraints independently of this editable text.</p>`:productionTab==='Versions'?`<section class="panel"><h3>Compare two saved versions</h3><div class="toolbar"><select id="compareA" aria-label="Version A">${versionOptions(e)}</select><select id="compareB" aria-label="Version B">${versionOptions(e)}</select><button id="compareVersions">Compare</button></div><div id="versionDiff"></div></section>${versions.filter(v=>v.lesson_id===e.id).map((x,i,arr)=>`<div class="list-row"><div class="grow"><b>Version ${arr.length-i} · ${esc(x.status)}</b><small>${esc(x.body.note)} · ${new Date(x.created_at).toLocaleString()} · ${esc(x.actor)}</small></div><button data-load-version="${x.id}">Inspect / create variation</button></div>`).join('')||empty('No versions yet','Save the first version below. Saved snapshots are never overwritten.')}`:productionTab==='Generate'?`<div class="split"><section class="panel"><h3>Production readiness</h3>${session.connections.checks.map(c=>`<div class="list-row"><span>${esc(c.name)}</span><span class="badge ${c.ready?'approved':''}">${c.ready?'Configured':'Needed'}</span></div>`).join('')}<p>Sia commercial rights: confirmed by owner. Only her approved voice will be used.</p>${siaReferencePicker()}<label for="referenceUpload">Or upload a prepared Sia frame for this setting</label><input type="file" id="referenceUpload" accept="image/png,image/jpeg,image/webp"><p class="subtle">One person only, portrait frame, approved outfit and face. The character board is a reference sheet, not a generation frame.</p>${d.referenceKey?`<img class="reference-preview" src="/api/media?key=${encodeURIComponent(d.referenceKey)}" alt="Uploaded Sia reference"><label><input id="referenceApproved" type="checkbox" ${d.referenceApproved?'checked':''}> I reviewed this reference frame</label>`:''}<div class="actions"><button id="generateNow" class="primary">Generate video</button><select id="sceneChoice" aria-label="Scene to regenerate">${d.scenes.map((s,i)=>`<option value="${i}">Scene ${i+1}</option>`).join('')}</select><button id="generateScene">Regenerate scene</button></div><p class="subtle">For your first short test, start from Connections → Prepare 10-second Sia test. Save a new version after any edit. Generation consumes provider credits only after setup is enabled. This setup allows one short test job. No automatic paid boost.</p></section><section class="panel"><h3>Generation history</h3>${jobs.filter(j=>versions.some(v=>v.id===j.version_id&&v.lesson_id===e.id)).map(j=>`<div class="job"><b>${esc(j.status)} · ${esc(j.stage)}</b><p>${esc(j.body.error||j.body.outputKind||'')}</p>${j.body.audioKey?`<audio controls src="/api/media?key=${encodeURIComponent(j.body.audioKey)}"></audio>`:''}${j.body.mediaKey?`<video controls playsinline src="/api/media?key=${encodeURIComponent(j.body.mediaKey)}"></video>`:''}${!['Completed','Failed','Held'].includes(j.status)?`<button data-advance-job="${j.id}">Resume / check progress</button>`:''}<small>Version ${esc(j.version_id.slice(0,8))} · ${esc(j.provider_id||'Provider task not yet submitted')}</small></div>`).join('')||empty('No generation jobs','Connect providers and save a version to generate a Sia presenter draft.')}</section></div>`:`<section class="panel"><h3>Review the whole package</h3><p>Script approval and final-media approval are separate. A final version needs identity, voice, language, captions, rights and safe-zone checks. Publishing stays held while final media and accounts are missing.</p><div class="toolbar"><label>Owner<input id="reviewOwner" value="${esc(state.edits[e.id]?.owner||e.owner||'Unassigned')}"></label><label>Due date<input id="reviewDue" type="date" value="${esc(state.edits[e.id]?.dueDate||e.dueDate||e.date)}"></label></div><label for="reviewNote">Review note</label><textarea id="reviewNote">${esc(state.edits[e.id]?.note||'')}</textarea><div class="actions"><button id="scriptReview">Send script for review</button><button id="scriptApprove">Approve script plan</button><button id="requestChanges">Request changes</button></div><h3>Final media checks</h3>${['identity','voice','captions','language','rights','safeZones'].map(k=>`<label><input type="checkbox" data-qa="${k}"> ${esc(k)}</label>`).join('')}<button id="approveFinal">Approve final media</button></section>`}<div class="version-save"><label for="versionNote">Version / change note</label><input id="versionNote" value="${esc(d.note||'')}" placeholder="e.g. Shortened the hook; kept the target sentence"><button class="primary" id="saveVersion">Save new version</button><button id="exportPackage">Export production package</button><span class="subtle">${v?'Inspecting saved '+v.id.slice(0,8):'Unsaved draft'} · saved versions stay immutable</span></div></div>`;$('#closeProduction').onclick=()=>{dialog.close();render()};dialog.querySelectorAll('[data-production-tab]').forEach(b=>b.onclick=()=>{captureDraft();productionTab=b.dataset.productionTab;showProduction()});bindProduction();if(!dialog.open)dialog.showModal();}
function versionOptions(e){return versions.filter(v=>v.lesson_id===e.id).map((v,i,a)=>`<option value="${v.id}">v${a.length-i}: ${esc(v.body.note)}</option>`).join('');}
function captureDraft(){const d=editorDraft;if($('#productionScript'))d.script=$('#productionScript').value;document.querySelectorAll('[data-scene-voice]').forEach(el=>{d.scenes[el.dataset.sceneVoice].voiceover=el.value;d.scenes[el.dataset.sceneVoice].captionText=el.value});document.querySelectorAll('[data-scene-shot]').forEach(el=>d.scenes[el.dataset.sceneShot].shot=el.value);if($('#productionPrompt'))d.prompt=$('#productionPrompt').value;if($('#productionPlatform'))d.platform=$('#productionPlatform').value;if($('#productionLanguage'))d.language=$('#productionLanguage').value;if($('#productionDuration'))d.duration=Number($('#productionDuration').value);if($('#referenceApproved'))d.referenceApproved=$('#referenceApproved').checked;if($('#versionNote'))d.note=$('#versionNote').value;}
function rebuildPrompt(){const e=byId(productionLesson),d=editorDraft;d.prompt=`SPEAKX / ${e.date} / ${e.topic}\nObjective: ${e.target}. Audience: ${e.persona}. Platform: ${d.platform}. 9:16 vertical. Planned ${d.duration}s; measure synthesized speech.\nSIA LOCK: only Sia appears and speaks. Use approved reference face, long centre-part dark wavy hair with caramel ends, outfit matching the selected approved frame, warm calm Hinglish delivery. No other faces, reflections or background people. No extra voices.\nSetting: ${e.location}. ${e.mapReveal?'One-second map reveal at 2–3s under the first answer; never delay the teaching line.':'No map overlay.'}\nVoice: approved Cartesia Sia voice. Exact transcript: ${d.script}\n${d.scenes.map((s,i)=>`SCENE ${i+1} ${s.startSeconds}–${s.endSeconds}s\nSIA: ${s.voiceover}\nSHOT: ${s.shot}\nEDIT: ${s.edit}\nCAPTIONS: ${s.voiceover}`).join('\n\n')}\nFINISHING: captions max2lines, synchronized to actual voice, no face overlap; reserve bottom20% and right12% for app UI. Exact supplied SpeakX logo after value, no opening logo. No invented app UI, testimonials or outcome claims.\nQA: face identity, commercial rights, English accuracy, lip sync, loudness, caption timing, mobile safe zones, complete answer, no other people. Captions/map/logo are deterministic finishing steps, not assumed in generated draft.`;d.prompt=withSiaReferencePolicy(d.prompt);}
function draftSrt(scenes){let n=0;const stamp=t=>{const ms=Math.round(t*1000);return `${String(Math.floor(ms/3600000)).padStart(2,'0')}:${String(Math.floor(ms/60000)%60).padStart(2,'0')}:${String(Math.floor(ms/1000)%60).padStart(2,'0')},${String(ms%1000).padStart(3,'0')}`};return scenes.flatMap(s=>{const words=s.voiceover.split(/\s+/),chunks=[];for(let i=0;i<words.length;i+=7)chunks.push(words.slice(i,i+7).join(' '));return chunks.map((c,i)=>`${++n}\n${stamp(s.startSeconds+(s.endSeconds-s.startSeconds)*i/chunks.length)} --> ${stamp(s.startSeconds+(s.endSeconds-s.startSeconds)*(i+1)/chunks.length)}\n${c}\n`)}).join('\n');}
async function saveVersion(){captureDraft();if(editorDraft.scenes.map(s=>s.voiceover.trim()).join(' ')!==editorDraft.script.trim())throw Error('Script and scene voiceovers differ. Use “Distribute revised script” or “Use scene edits as final script” first.');if(!editorDraft.note.trim())throw Error('Add a change note for this version.');editorDraft.parentId=versionFor(byId(productionLesson))?.id||null;const v=await api('versions',{method:'POST',body:editorDraft});versions.unshift(v);productionVersion=v.id;toast('New immutable version saved.');showProduction();return v;}
function bindProduction(){bindSiaReferencePicker();const safe=fn=>async()=>{try{await fn()}catch(e){toast(e.message+(e.missing?' Needed: '+e.missing.join(', '):''))}};$('#saveVersion').onclick=safe(saveVersion);$('#exportPackage').onclick=()=>{captureDraft();download(productionLesson+'-production.json',JSON.stringify({episode:byId(productionLesson),draft:editorDraft,versions:versions.filter(v=>v.lesson_id===productionLesson)},null,2),'application/json')};if($('#rebuildPrompt'))$('#rebuildPrompt').onclick=()=>{captureDraft();rebuildPrompt();showProduction()};if($('#syncSceneScript'))$('#syncSceneScript').onclick=()=>{captureDraft();editorDraft.script=editorDraft.scenes.map(s=>s.voiceover.trim()).join(' ');rebuildPrompt();showProduction()};if($('#redistribute'))$('#redistribute').onclick=()=>{captureDraft();const words=editorDraft.script.trim().split(/\s+/);editorDraft.scenes.forEach((s,i,a)=>{s.voiceover=words.slice(Math.round(i*words.length/a.length),Math.round((i+1)*words.length/a.length)).join(' ');s.captionText=s.voiceover});rebuildPrompt();showProduction();toast('Scene text redistributed. Review sentence boundaries and pacing before saving.')};if($('#exportSrt'))$('#exportSrt').onclick=()=>{captureDraft();download(productionLesson+'-DRAFT-not-aligned.srt',draftSrt(editorDraft.scenes))};document.querySelectorAll('[data-load-version]').forEach(b=>b.onclick=()=>{productionVersion=b.dataset.loadVersion;editorDraft=draftFor(byId(productionLesson));productionTab='Script';showProduction()});if($('#compareVersions'))$('#compareVersions').onclick=()=>{const a=versions.find(v=>v.id===$('#compareA').value),b=versions.find(v=>v.id===$('#compareB').value);$('#versionDiff').innerHTML=a&&b?`<p>${a.id===b.id?'Select different versions to see changes.':'Changed fields: '+['script','prompt','language','platform','duration','scenes','referenceKey'].filter(k=>JSON.stringify(a.body[k])!==JSON.stringify(b.body[k])).join(', ')}</p><div class="split"><pre>${esc(a.body.script)}</pre><pre>${esc(b.body.script)}</pre></div>`:empty('Save two versions','Version comparison becomes available after saving.')};if($('#referenceUpload'))$('#referenceUpload').onchange=async ev=>{const f=ev.target.files[0];if(!f)return;try{if(f.size>5*1024*1024)throw Error('Choose an image smaller than 5 MB.');const r=await fetch('/api/reference',{method:'POST',headers:{'Content-Type':f.type},body:f});const b=await r.json();if(!r.ok)throw Error(b.error);editorDraft.referenceKey=b.key;delete editorDraft.referenceAssetId;editorDraft.referenceApproved=false;showProduction()}catch(e){toast(e.message)}};async function generate(sceneIndex=null){captureDraft();const v=versionFor(byId(productionLesson));if(!v)throw Error('Save a version before generating.');const comparable=o=>JSON.stringify([o.script,o.prompt,o.scenes,o.referenceKey,o.referenceApproved,o.platform,o.language,o.duration]);if(comparable(v.body)!==comparable(editorDraft))throw Error('Save these edits as a new version before generating.');const j=await api('jobs',{method:'POST',body:{versionId:v.id,sceneIndex}});jobs=[j,...jobs.filter(x=>x.id!==j.id)];if(providerSettings)providerSettings.remainingTests=0;showProduction();toast('Test job saved. Producing Sia’s audio and video…');runGenerationJob(j.id);}if($('#generateNow'))$('#generateNow').onclick=safe(()=>generate());if($('#generateScene'))$('#generateScene').onclick=safe(()=>generate(Number($('#sceneChoice').value)));document.querySelectorAll('[data-advance-job]').forEach(b=>b.onclick=safe(async()=>{b.disabled=true;await runGenerationJob(b.dataset.advanceJob)}));for(const [selector,status] of [['scriptReview','In review'],['scriptApprove','Approved demo'],['requestChanges','Changes requested']])if($('#'+selector))$('#'+selector).onclick=()=>{if(selector!=='scriptReview'&&!canApprove())return toast('An approver is required.');state.edits[productionLesson]={...state.edits[productionLesson],status,note:$('#reviewNote').value,owner:$('#reviewOwner').value,dueDate:$('#reviewDue').value};saveGrowth('Script planning status: '+status,productionLesson);toast('Planning status saved. Final media remains unapproved.')};if($('#approveFinal'))$('#approveFinal').onclick=safe(async()=>{const v=versionFor(byId(productionLesson));if(!v)throw Error('Save and generate a version first.');const qa=Object.fromEntries([...document.querySelectorAll('[data-qa]')].map(e=>[e.dataset.qa,e.checked]));await api('versions/'+v.id+'/approve',{method:'POST',body:{qa}})});}
function growthApprovals(){return heading('Approve the exact version.','Planning review is separate from final-media approval')+`<section class="panel"><p>Draft scripts can be approved for production. A presenter draft cannot be approved for publishing until captions, the final edit and account checks are complete.</p>${all().filter(e=>['In review','Changes requested','Approved demo'].includes(e.status)).map(row).join('')||empty('No scripts awaiting review','Open a lesson → Review → Send script for review.')}</section><section class="panel"><h2>Audit history</h2>${(state.audit||[]).slice(0,20).map(x=>`<div class="list-row"><small>${esc(x.at)}</small><span>${esc(x.action)}</span><small>${esc(x.id)}</small></div>`).join('')}</section>`;}
function growthQueue(){return heading('Every placement accounted for.','180 planned units · 240 individual posts / Story frames · IST')+`<section class="panel"><p><b>Publishing held.</b> No social access tokens, final captioned media or publish receipts are connected. These are planned slots, not scheduled posts on the platforms.</p><p>Scheduler design: check approved version → account capability → due slot → submit once → save receipt → reconcile uncertain responses before retry. Pause prevents dispatch.</p></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>Day</th><th>Lesson</th><th>YouTube</th><th>Instagram</th><th>Facebook</th><th>X</th><th>Story set</th><th>State</th></tr></thead><tbody>${all().map(e=>`<tr><td>${e.date}</td><td><button data-open="${e.id}">${esc(e.topic)}</button></td><td>${e.timeYT}</td><td>${e.timeIG}</td><td>${e.timeFB}</td><td>08:30 / 19:00</td><td>13:00 · 3 frames</td><td>Held</td></tr>`).join('')}</tbody></table></div></section>`;}
const fmt=(v,suffix='')=>Number.isFinite(v)?(Math.abs(v)>=1000?v.toLocaleString('en-IN',{maximumFractionDigits:1}):Number(v.toFixed(1)))+suffix:'N/A';
function cohort(){return G.latest(state.measurements||[]).filter(r=>r.platform===metricsPlatform&&r.window===metricsWindow&&r.distribution==='organic');}
function sumAvailable(rs,key){const values=rs.map(r=>r[key]).filter(Number.isFinite);return values.length?values.reduce((a,b)=>a+b,0):null;}
function performanceView(){const rs=cohort(),dv=rs.map(G.derived);return heading('Useful views. Useful decisions.','Actual imports only · no fabricated growth curves',`<button id="exportMetrics">Export observations</button>`)+`<div class="toolbar"><select id="metricPlatform" aria-label="Analytics platform">${['YouTube','Instagram','Facebook','X'].map(x=>`<option ${metricsPlatform===x?'selected':''}>${x}</option>`).join('')}</select><select id="metricWindow" aria-label="Observation window">${['24h','72h','7d','30d','custom'].map(x=>`<option ${metricsWindow===x?'selected':''}>${x}</option>`).join('')}</select><label>Import normalized JSON<input type="file" id="metricsImport" accept="application/json"></label><button id="metricTemplate">Download import template</button></div><p class="subtle">One platform and one post-age window at a time. Counts show available-field coverage below; missing is not zero. Reach across posts is not deduplicated. Paid rows are excluded.</p><div class="stats"><article><span>Views · ${metricsPlatform}</span><strong>${fmt(sumAvailable(rs,'views'))}</strong><small>${rs.filter(r=>Number.isFinite(r.views)).length}/${rs.length} posts with field</small></article><article><span>Median average view duration</span><strong>${fmt(G.median(dv.map(r=>r.avd)),'s')}</strong><small>${dv.filter(r=>Number.isFinite(r.avd)).length}/${rs.length} posts with field</small></article><article><span>Median average % viewed</span><strong>${fmt(G.median(dv.map(r=>r.apv)),'%')}</strong><small>Per-post median; may exceed 100% with repeats</small></article><article><span>Attributed revenue · INR</span><strong>${fmt(sumAvailable(rs.filter(r=>r.attribution==='direct'&&r.currency==='INR'),'revenue'))}</strong><small>Direct imported attribution only</small></article></div><section class="panel"><h2>Post-level evidence</h2>${rs.length?`<div class="table-wrap"><table><thead><tr><th>Post</th><th>Views</th><th>AVD</th><th>APV</th><th>Scroll stop</th><th>Thumbnail CTR</th><th>Follows / 1k viewers</th><th>Engagement / reach</th></tr></thead><tbody>${rs.map(r=>{const d=G.derived(r);return `<tr><td>${esc(r.postId)}<small>${esc(r.viewDefinition)} · ${esc(r.source)}</small></td><td>${fmt(r.views)}</td><td>${fmt(d.avd,'s')}</td><td>${fmt(d.apv,'%')}</td><td>${fmt(d.scrollStop,'%')}</td><td>${fmt(d.thumbnailCtr,'%')}</td><td>${fmt(d.followsPer1000)}</td><td>${fmt(d.engagementPerReach,'%')}</td></tr>`}).join('')}</tbody></table></div>`:empty('No analytics in this cohort','Connect an account or import a real platform export in the documented schema. Public profile counts cannot fill these fields.')}</section><section class="panel"><h2>Verified account snapshot · September 21</h2>${objectCard(strategy.verifiedAccountSnapshot)}<h3>Strategy implications</h3>${objectCard(strategy.strategicUpdate)}</section><section class="panel"><h2>Measurement dictionary</h2><p>YouTube Shorts feed selection is not thumbnail CTR. Engaged views, starts, reach and impressions stay distinct. AVD uses the supplied platform value; if derived, its denominator is stated. Do not compare view counts across platforms as if their definitions match.</p>${objectCard(strategy.metricDictionary)}</section>`;}
function retentionView(){const available=(state.measurements||[]).filter(r=>r.retention?.length>1);const selectedRow=available.find(r=>r.postId===state.retentionPost)||available[0];const threshold=state.thresholds?.retentionDrop??12;return heading('Find the moment viewers leave.','Graph evidence → possible explanation → one edit to test')+`<section class="panel"><div class="toolbar"><select id="retentionPost" aria-label="Retention post">${available.map(r=>`<option value="${esc(r.postId)}" ${r===selectedRow?'selected':''}>${esc(r.platform+' · '+r.postId)}</option>`).join('')||'<option>No retention data</option>'}</select><label>Flag a drop of at least<input id="retentionThreshold" type="number" min="1" max="100" value="${threshold}">percentage points</label><button id="saveThreshold">Apply threshold</button><button data-go="reports">Import data</button></div>${selectedRow?retentionChart(selectedRow):empty('No retention curve imported','Import timestamps and percentages from a real retention report. Screenshots need transcription into the template; they are not silently interpreted as measured data.')}<p class="subtle">A drop or spike is a signal, not proof of why it happened. Compare comments, pacing and the actual scene before deciding.</p></section>${selectedRow?G.retention(selectedRow,threshold).map(x=>`<section class="panel"><h3>${x.at}s · ${esc(x.diagnosis)}</h3>${objectCard(x)}</section>`).join('')||'<section class="panel">No changes exceed this threshold. This is not proof that the video is optimal.</section>':''}`;}
function retentionChart(r){const w=900,h=240,max=Math.max(100,...r.retention.map(x=>x.percent)),duration=r.duration||Math.max(...r.retention.map(x=>x.second));const points=r.retention.map(x=>`${45+x.second/duration*(w-65)},${h-30-x.percent/max*(h-50)}`).join(' ');return `<svg class="retention-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Audience retention for ${esc(r.postId)}"><line x1="45" y1="${h-30}" x2="${w-15}" y2="${h-30}" stroke="#ccc"/><line x1="45" y1="20" x2="45" y2="${h-30}" stroke="#ccc"/><polyline points="${points}" fill="none" stroke="#ff5000" stroke-width="3"/><text x="0" y="24">${max}%</text><text x="10" y="${h-28}">0%</text><text x="45" y="${h-8}">0s</text><text x="${w-45}" y="${h-8}">${duration}s</text></svg>`;}
function generatedReview(kind){const rs=cohort();const comparisons=G.compare(rs,'apv',state.thresholds?.minViews??500,state.thresholds?.minPosts??3);return {period:kind==='weekly'?'Selected weekly review':'October 1–30, 2026',platform:metricsPlatform,postAgeWindow:metricsWindow,observations:rs.length,dataStatus:rs.length?'Imported; coverage varies':'No account analytics available',medianAPV:G.median(rs.map(r=>G.derived(r).apv)),medianAVD:G.median(rs.map(r=>G.derived(r).avd)),matchedCohorts:comparisons.map(c=>({cohort:c.key,median:c.baseline,top:c.posts.slice(0,5).map(r=>({post:r.postId,value:r.value})),bottom:c.posts.slice(-5).map(r=>({post:r.postId,value:r.value}))})),decision:comparisons.length?'Review matched cohorts and comments; test one change before scaling.':'Insufficient matched observations to declare a winner. Continue the baseline plan.',stop:'No unproven growth promise or duplicate mass reposting.',start:'Capture comparable 24h, 72h and 7d snapshots.',continue:'One specific speaking task and a same-episode answer.',scale:'Only after repeated matched wins with follow/trial guardrails.',retest:'Opening clarity, one variable at a time.',owner:'Social media manager',deadline:kind==='weekly'?'Next Monday 10:30 IST':'October 30, 17:00 IST'};}
function reviewView(kind){const note=state.reviews?.[kind]||'';return heading(kind==='weekly'?'Turn the week into a better next week.':'Decide what earns another month.',kind==='weekly'?'Oct 5 / 12 / 19 / 26 · 10:30 IST':'October 30 · 17:00 IST · closeout for this 30-day campaign',`<button id="exportReview" data-kind="${kind}">Export review</button>`)+`<section class="panel"><p>Review the selected performance cohort: ${esc(metricsPlatform)} · ${metricsWindow}. Change it in Performance. Top/bottom lists require at least the configured sample floor and matched duration, platform and view definition.</p>${objectCard(generatedReview(kind))}</section><section class="panel"><h2>Review checklist</h2>${objectCard(strategy.reviews?.[kind]||strategy.reviews)}</section><section class="panel"><label for="reviewDecisions">Manager decisions, owners and deadlines</label><textarea id="reviewDecisions" rows="8" placeholder="Stop / Start / Continue / Scale / Retest; evidence, accountable owner, due date">${esc(note)}</textarea><button id="saveReviewDecisions" data-kind="${kind}">Save review decisions</button></section>`;}
function experimentsView(){return heading('One variable. One learning.','12 planned experiments · activate only 2–3 at once')+`<p class="subtle">Sample floors are planning heuristics, not statistical power calculations. Sequential organic tests are observational and can be confounded by topic, audience and distribution.</p><div class="cards">${(strategy.experiments||[]).map((x,i)=>`<section class="panel">${objectCard(x)}<label for="experiment${i}">Test status</label><select data-experiment="${i}" id="experiment${i}">${['Backlog','Running','Inconclusive','Keep control','Adopt variation'].map(s=>`<option ${(state.experimentState||{})[i]?.status===s?'selected':''}>${s}</option>`).join('')}</select><label for="learning${i}">Evidence / learning</label><textarea id="learning${i}" data-learning="${i}">${esc((state.experimentState||{})[i]?.learning||'')}</textarea><button data-save-experiment="${i}">Save experiment</button></section>`).join('')}</div>`;}
function monetizationView(){const rows=cohort();const direct=rows.filter(r=>r.attribution==='direct'&&r.currency==='INR');return heading('Earn trust before asking for a trial.','Organic → speaking practice → qualified product intent')+`<div class="stats"><article><span>Link clicks</span><strong>${fmt(sumAvailable(rows,'linkClicks'))}</strong><small>Imported, same cohort</small></article><article><span>Trials</span><strong>${fmt(sumAvailable(rows,'trials'))}</strong><small>Tracking required</small></article><article><span>Paid subscriptions</span><strong>${fmt(sumAvailable(rows,'paid'))}</strong><small>No sales inferred from views</small></article><article><span>Direct revenue · INR</span><strong>${fmt(sumAvailable(direct,'revenue'))}</strong><small>Assisted and unattributed stay separate</small></article></div><section class="panel">${objectCard(strategy.monetization)}</section><section class="panel"><h2>Campaign link builder</h2><p>Use an approved destination. Validate app deep-link parameters in your attribution provider before publishing.</p><label for="linkBase">Landing page</label><input id="linkBase" type="url" value="https://speakx.ai/"><label for="linkSource">Platform</label><select id="linkSource"><option>instagram</option><option>youtube</option><option>facebook</option><option>x</option></select><label for="linkContent">Lesson / version</label><input id="linkContent" value="sia-2026-10-01-v1"><button id="buildLink">Build tagged link</button><pre id="taggedLink"></pre></section><section class="panel"><h2>Paid promotion policy</h2><p>₹0 planned ad spend. Revisit boosting only after a repeatable organic winner, conversion tracking and an explicit spend decision. Organic does not remove voice, video-generation or platform API costs.</p></section>`;}
function recommendations(){const metric=state.thresholds?.primaryMetric||'apv';const cohorts=G.compare(state.measurements||[],metric,state.thresholds?.minViews??500,state.thresholds?.minPosts??3);if(!cohorts.length)return [{title:'Build a trustworthy baseline',basis:'No cohort meets the minimum comparable-data rules.',action:'Run the 30-day plan; import 24h/72h/7d snapshots. Start with hook tests on flagship lessons.',confidence:'Cold start: editorial hypothesis',lesson:all()[0]?.id},{title:'Balance direct lessons and real situations',basis:'19 studio episodes, 11 location episodes; no measured format winner yet.',action:'Match studio and location lessons by duration, learner level and topic before interpreting results.',confidence:'Cold start: editorial hypothesis',lesson:all()[7]?.id},{title:'Find the next learner question',basis:'Comments have not been connected.',action:'Add real questions to Idea backlog; prioritize specific speaking situations over broad “learn English” topics.',confidence:'Needs evidence',lesson:all()[14]?.id}];const output=[];for(const c of cohorts){const top=c.posts[0],low=c.posts[c.posts.length-1];output.push({title:'Retest the strongest matched pattern',basis:`${c.key}: ${top.postId} ${metric} ${top.value.toFixed(1)} vs median ${c.baseline.toFixed(1)} across ${c.posts.length} comparable posts.`,action:'Repeat the learning need with a new sentence. Keep format constant; check follow and conversion guardrails before allocating more slots.',confidence:'Observed association, not causal proof',lesson:top.lessonId},{title:'Rework one weak section',basis:`${low.postId}: ${low.value.toFixed(1)} vs cohort median ${c.baseline.toFixed(1)}.`,action:'Inspect first-frame relevance and retention graph. Create a hook-only variation rather than deleting the original.',confidence:'Hypothesis requiring scene review',lesson:low.lessonId});}return output;}
function recommendationView(){return heading('Let evidence choose the next test.','Transparent rules · editable sample floors · no black-box viral promises')+`<section class="panel"><div class="toolbar"><label>Minimum views / engaged views<input id="minViews" type="number" min="1" value="${state.thresholds?.minViews??500}"></label><label>Minimum comparable posts<input id="minPosts" type="number" min="3" value="${state.thresholds?.minPosts??3}"></label><button id="saveRecRules">Save rules</button></div><p>Rules compare organic posts within the same platform, observation window, view definition and 10-second duration band. The initial recommendation split is editorial; once evidence exists, consider 60% repeated winning needs, 25% adjacent needs and 15% experiments. Avoid claiming “proven” from one post.</p></section>${recommendations().map((r,i)=>`<section class="panel"><span class="tag">${esc(r.confidence)}</span><h3>${esc(r.title)}</h3><p>${esc(r.basis)}</p><p>${esc(r.action)}</p><div class="actions">${byId(r.lesson)?`<button data-open="${r.lesson}">Create a variation</button>`:''}<button data-recommendation="${i}">Add as experiment brief</button></div></section>`).join('')}`;}
function growthPlan(){return heading('The operating playbook.','30-day scope · roles, exceptions, production and learning')+`<section class="panel docs">${[['phase1-guide.md','Phase 1: script versions, video review and approved download'],['growth-strategy.md','Growth strategy, positioning, monetization and measurement'],['october-content.md','All 30 episode scripts and full generation prompts'],['growth-implementation.md','Working features, connection steps and remaining production gates'],['automation-blueprint.md','Agent contracts, publishing and recovery design'],['api-notes.md','Verified provider and platform integration notes'],['manager-guide.md','Manager workflow and handoff']].map(([f,t])=>`<a href="docs/${f}" data-doc="${f}">${esc(t)}<small>Open document</small></a>`).join('')}<a href="october.json" download>Download all 30 production packages</a><a href="strategy.json" download>Download strategy and research data</a><button id="exportCSV">Export calendar CSV</button></section>`;}
function connectionsView(){return heading('Connect once. Keep control.','Private workspace · provider secrets stay on the server')+`<div class="split">${providerSettingsView()}${PhaseOne.settings()}<section class="panel"><h2>Social accounts</h2>${[['YouTube','https://www.youtube.com/@speakx_ai'],['Instagram','https://www.instagram.com/speakx_ai/'],['Facebook','https://www.facebook.com/speakxai'],['X','https://x.com/SpeakxOnX']].map(([n,u])=>`<div class="list-row"><a href="${u}" target="_blank" rel="noreferrer">${n} profile</a><span class="badge">Manual publishing</span></div>`).join('')}<p>Instagram account insights were read in Chrome; recurring API ingestion is not connected. Other private analytics require account-owner access. Browser access for a one-time audit is separate from the OAuth connection required for recurring ingestion and publishing.</p></section></div><section class="panel"><h2>Workspace & recovery</h2><p>Signed in as ${esc(session.user.email)} · ${esc(session.user.role)}. Planning changes are stored in the private workspace. A second manager’s overlapping save is held for review, not silently overwritten.</p><button id="growthBackup">Export workspace backup</button><p class="subtle">Sharing with a social media manager requires adding their account to this private site and assigning a server role. No additional person has been granted access.</p></section>`;}
function importTemplate(){return [{postId:'REPLACE_WITH_REAL_POST_ID',lessonId:'SIA-2026-10-01',versionId:null,platform:'YouTube',publishedAt:'2026-10-01T13:00:00Z',snapshotAt:'2026-10-04T13:00:00Z',window:'72h',distribution:'organic',source:'YouTube Studio export: filename / report range',viewDefinition:'Shorts starts and replays; engagedViews separate',duration:35,views:null,engagedViews:null,averageViewDuration:null,reach:null,viewers:null,impressions:null,thumbnailImpressions:null,thumbnailClicks:null,shownInFeed:null,viewedInFeed:null,likes:null,comments:null,shares:null,saves:null,followersGained:null,profileVisits:null,linkClicks:null,landingVisits:null,installs:null,trials:null,paid:null,renewals:null,revenue:null,currency:'INR',attribution:'unattributed',cost:null,retention:[]}];}
function bindGrowth(){document.querySelectorAll('[data-gen-open]').forEach(b=>b.onclick=()=>openDetail(b.dataset.genOpen,'Generate'));if($('#growthSearch')){const filter=()=>{const q=$('#growthSearch').value.toLowerCase(),s=$('#growthSetting').value,f=$('#growthFlagship').value,j=$('#growthFunnel').value;$('#growthLessons').innerHTML=growthRows(all().filter(e=>(s==='all'||e.settingMode===s)&&(f==='all'||e.flagship)&&(j==='all'||j===e.contentJob)&&JSON.stringify(e).toLowerCase().includes(q)));document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openDetail(b.dataset.open));};['growthSearch','growthSetting','growthFlagship','growthFunnel'].forEach(x=>$('#'+x).oninput=filter);}if($('#addIdea'))$('#addIdea').onclick=()=>{if(!editable())return;const title=$('#ideaTitle').value.trim(),evidence=$('#ideaEvidence').value.trim();if(!title||!evidence)return toast('Add an idea and its evidence or hypothesis.');(state.ideas??=[]).unshift({id:crypto.randomUUID(),title,evidence,status:'Idea',at:new Date().toISOString()});saveGrowth('Idea captured');render()};document.querySelectorAll('[data-idea-promote]').forEach(b=>b.onclick=()=>{const i=state.ideas.find(x=>x.id===b.dataset.ideaPromote);i.status='Brief requested';saveGrowth('Idea promoted',i.id);render()});if($('#metricPlatform'))$('#metricPlatform').onchange=()=>{metricsPlatform=$('#metricPlatform').value;render()};if($('#metricWindow'))$('#metricWindow').onchange=()=>{metricsWindow=$('#metricWindow').value;render()};if($('#metricTemplate'))$('#metricTemplate').onclick=()=>download('SpeakX-analytics-template.json',JSON.stringify(importTemplate(),null,2),'application/json');if($('#exportMetrics'))$('#exportMetrics').onclick=()=>download('SpeakX-observations.json',JSON.stringify(state.measurements||[],null,2),'application/json');if($('#metricsImport'))$('#metricsImport').onchange=async ev=>{try{const f=ev.target.files[0];if(!f)return;if(f.size>3*1024*1024)throw Error('Use a JSON file smaller than 3 MB.');const rows=G.validate(JSON.parse(await f.text()));if(rows.some(r=>r.postId==='REPLACE_WITH_REAL_POST_ID'))throw Error('Replace template identifiers with real post data.');const byKey=new Map((state.measurements||[]).map(r=>[[r.platform,r.postId,r.snapshotAt].join('|'),r]));rows.forEach(r=>byKey.set([r.platform,r.postId,r.snapshotAt].join('|'),r));state.measurements=[...byKey.values()];saveGrowth('Imported '+rows.length+' metric observations');render();toast('Imported with source labels. Missing values remain N/A.')}catch(e){toast(e.message)}};if($('#retentionPost'))$('#retentionPost').onchange=()=>{state.retentionPost=$('#retentionPost').value;render()};if($('#saveThreshold'))$('#saveThreshold').onclick=()=>{const v=Number($('#retentionThreshold').value);if(v<1||v>100)return toast('Choose 1–100 percentage points.');state.thresholds={...state.thresholds,retentionDrop:v};saveGrowth('Retention rule updated');render()};if($('#saveReviewDecisions'))$('#saveReviewDecisions').onclick=()=>{(state.reviews??={})[$('#saveReviewDecisions').dataset.kind]=$('#reviewDecisions').value;saveGrowth('Review decisions saved');toast('Review saved.')};if($('#exportReview'))$('#exportReview').onclick=()=>{const kind=$('#exportReview').dataset.kind;download('SpeakX-'+kind+'-review.json',JSON.stringify({...generatedReview(kind),managerDecisions:state.reviews?.[kind]||''},null,2),'application/json')};document.querySelectorAll('[data-save-experiment]').forEach(b=>b.onclick=()=>{const i=b.dataset.saveExperiment,status=$('#experiment'+i).value;if(status==='Running'&&Object.values(state.experimentState||{}).filter(x=>x.status==='Running').length>=3&&state.experimentState?.[i]?.status!=='Running')return toast('Finish or pause a running experiment first; maximum three active.');(state.experimentState??={})[i]={status,learning:$('#learning'+i).value,at:new Date().toISOString()};saveGrowth('Experiment updated',i);toast('Experiment saved.')});if($('#buildLink'))$('#buildLink').onclick=()=>{try{const url=new URL($('#linkBase').value);if(url.protocol!=='https:')throw Error();url.searchParams.set('utm_source',$('#linkSource').value);url.searchParams.set('utm_medium','organic_social');url.searchParams.set('utm_campaign','sia_october_2026');url.searchParams.set('utm_content',$('#linkContent').value);$('#taggedLink').textContent=url.href;}catch{toast('Enter a valid HTTPS landing page.')}};if($('#saveRecRules'))$('#saveRecRules').onclick=()=>{const a=Number($('#minViews').value),b=Number($('#minPosts').value);if(!Number.isInteger(a)||a<1||!Number.isInteger(b)||b<3)return toast('Use a positive view floor and at least three comparable posts.');state.thresholds={...state.thresholds,minViews:a,minPosts:b};saveGrowth('Recommendation rules updated');render()};document.querySelectorAll('[data-recommendation]').forEach(b=>b.onclick=()=>{const r=recommendations()[b.dataset.recommendation];(state.ideas??=[]).unshift({id:crypto.randomUUID(),title:r.title,evidence:r.basis+' '+r.action,status:'Experiment brief',at:new Date().toISOString()});saveGrowth('Recommendation added to backlog');toast('Saved to Idea backlog.')});if($('#refreshConnections'))$('#refreshConnections').onclick=async()=>{try{session=await api('session');render()}catch(e){toast(e.message)}};if($('#growthBackup'))$('#growthBackup').onclick=()=>download('SpeakX-workspace-backup.json',JSON.stringify({state,episodes:all(),versions,jobs},null,2),'application/json');document.querySelectorAll('.fact p').forEach(el=>{if(/^https:\/\/[^\s]+$/.test(el.textContent)){const a=document.createElement('a');a.href=el.textContent;a.textContent=el.textContent;a.target='_blank';a.rel='noreferrer';el.replaceChildren(a)}});if(!editable())document.querySelectorAll('#main input,#main textarea,#main select,#main button').forEach(el=>{if(!el.dataset.go&&!el.dataset.open)el.disabled=true});}
exportCSV=function(){const cols=['id','date','day','show','topic','persona','pillar','contentJob','language','settingMode','location','timeYT','timeIG','timeFB','status','script','finalPrompt'];download('SpeakX-30-day-calendar.csv',[cols.join(','),...all().map(e=>cols.map(k=>'"'+String(e[k]??'').replaceAll('"','""')+'"').join(','))].join('\n'),'text/csv')};
(async()=>{try{const [data,s,me,w,vs,js]=await Promise.all([fetch('october.json').then(r=>r.json()),fetch('strategy.json').then(r=>r.json()),api('session'),api('workspace'),api('versions'),api('jobs')]);episodes=data;strategy=s;session=me;providerSettings=me.user.role==='Owner'?await api('provider-settings'):null;versions=vs;jobs=js;workspaceRevision=w.revision;if(w.state)state={...state,...w.state};else state={...state,edits:{},audit:[],ideas:[],measurements:[]};state.role=me.user.role;await PhaseOne.bootstrap();document.querySelector('.notice').innerHTML='October 1–30 · Phase 1 · Download & publish manually <span id="saveState">Saved workspace</span>';document.querySelector('.sidebar-foot small').textContent=me.user.role+' · private workspace';render();}catch(e){$('#main').innerHTML=`<section class="panel"><h1>Workspace unavailable</h1><p>${esc(e.message)}</p><button onclick="location.reload()">Retry connection</button><p>Your existing private site content remains in the saved version. Planning will load when storage is available.</p></section>`;}})();
